-- Git 세트 368. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_git_stash_tag_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 368, 'Git 임시 보관과 태그, 커밋 골라 가져오기: stash, tag, cherry-pick', '작은 Git 저장소에서 작업 흐름을 돕는 명령을 손에 익힙니다. 하던 변경을 stash 로 치우고 목록을 보고 pop 으로 되살리고, 가벼운 태그와 메시지가 있는 태그를 달고 옛 커밋에 태그를 달고 패턴으로 찾고, cherry-pick 으로 다른 브랜치의 커밋 하나만 가져오며 -x 로 출처를 남깁니다. 채점은 저장소의 실제 상태를 확인합니다.', 'linux', 'Git'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 368);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 1, '하던 작업을 잠시 치워 두기 (git stash)', '`/tmp/lab/proj` 에서 `README.md` 를 고치던 중입니다(아직 커밋하지 않음). 급한 일이 생겨 **하던 변경을 잠시 치워 두고** 작업 폴더를 깨끗하게 만드세요. 변경을 버리면 안 됩니다.', '`git stash` 는 커밋하지 않은 변경을 임시 보관함에 넣고 작업 폴더를 마지막 커밋 상태로 되돌립니다. `git status` 로 확인해 보세요.', 'cd /tmp/lab/proj
git status --short
git stash
git status --short

# git stash : 커밋하지 않은 변경을 보관함에 넣고 작업 폴더를 깨끗하게 한다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ -z \\"$(git -C /tmp/lab/proj status --porcelain)\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj stash list | wc -l)\\" -eq 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "작업 폴더가 깨끗하다", "cmd": ["sh", "-c", "[ -z \\"$(git -C /tmp/lab/proj status --porcelain)\\" ]"]}, {"label": "보관함(stash)에 항목이 1개 있다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj stash list | wc -l)\\" -eq 1 ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 2, '보관함 목록 보기 (git stash list)', '`README.md` 의 변경을 `stash` 로 치워 둔 뒤, **보관함 목록** 을 **`/tmp/lab/stash_list.txt`** 에 저장하세요.', '먼저 변경을 stash 한 다음 `git stash list` 를 실행합니다. 목록의 `stash@{0}` 이 가장 최근 항목입니다.', 'cd /tmp/lab/proj
git stash
git stash list > /tmp/lab/stash_list.txt
cat /tmp/lab/stash_list.txt

# git stash list : 보관함에 든 항목들. stash@{0} 이 가장 최근', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/stash_list.txt)\\" -eq 1 ] && [ \\"$(cat /tmp/lab/stash_list.txt)\\" = \\"$(git -C /tmp/lab/proj stash list)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "stash_list.txt 가 보관함 목록 1줄과 같다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/stash_list.txt)\\" -eq 1 ] && [ \\"$(cat /tmp/lab/stash_list.txt)\\" = \\"$(git -C /tmp/lab/proj stash list)\\" ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 3, '치워 둔 작업 되살리기 (git stash pop)', '(1) `README.md` 의 변경을 stash 한 직후의 `git status --short` 출력을 **`/tmp/lab/clean.txt`** 에 저장하세요(깨끗하면 빈 파일). (2) 그다음 치워 둔 변경을 **되살리고 보관함에서도 지운 뒤**, `git status --short` 출력을 **`/tmp/lab/back.txt`** 에 저장하세요.', '`git stash pop` 은 가장 최근 보관 항목을 작업 폴더에 되살리고 보관함에서 지웁니다. 상태는 `git status --short` 로 봅니다.', 'cd /tmp/lab/proj
git stash
git status --short > /tmp/lab/clean.txt
git stash pop
git status --short > /tmp/lab/back.txt
cat /tmp/lab/back.txt

# git stash pop : 되살리고 보관함에서 지운다 (apply 는 되살리기만 한다)', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ -f /tmp/lab/clean.txt ] && [ ! -s /tmp/lab/clean.txt ] ) && ( [ \\"$(cat /tmp/lab/back.txt)\\" = \\"$(git -C /tmp/lab/proj status --short)\\" ] && grep -q \\"README.md\\" /tmp/lab/back.txt ) && ( [ \\"$(git -C /tmp/lab/proj stash list | wc -l)\\" -eq 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "clean.txt 가 빈 파일이다 (stash 직후 깨끗했다)", "cmd": ["sh", "-c", "[ -f /tmp/lab/clean.txt ] && [ ! -s /tmp/lab/clean.txt ]"]}, {"label": "back.txt 가 현재 상태와 같고 README.md 수정이 보인다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lab/back.txt)\\" = \\"$(git -C /tmp/lab/proj status --short)\\" ] && grep -q \\"README.md\\" /tmp/lab/back.txt"]}, {"label": "보관함이 비었다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj stash list | wc -l)\\" -eq 0 ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 4, '가벼운 태그 달기 (git tag)', '지금 가리키는 커밋(`HEAD`)에 태그 `v1.0` 을 다세요. (메시지 없는 가벼운 태그)', '`git tag 이름` 은 현재 커밋에 태그를 답니다. `git tag` 로 목록을 확인하세요.', 'cd /tmp/lab/proj
git tag v1.0
git tag

# git tag 이름 : 현재 커밋에 가벼운(lightweight) 태그', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj rev-parse v1.0)\\" = \\"$(git -C /tmp/lab/proj rev-parse HEAD)\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj cat-file -t v1.0)\\" = \\"commit\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "v1.0 이 HEAD 를 가리킨다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-parse v1.0)\\" = \\"$(git -C /tmp/lab/proj rev-parse HEAD)\\" ]"]}, {"label": "가벼운 태그(commit 을 직접 가리킴)이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj cat-file -t v1.0)\\" = \\"commit\\" ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 5, '메시지가 있는 태그 (annotated)', '`HEAD` 에 **메시지가 있는** 태그 `v1.1` 을 다세요. 메시지는 `release 1.1` 입니다.', '`-a` 로 메시지가 있는(annotated) 태그를 만들고 `-m` 으로 메시지를 줍니다. `git tag -n1` 로 메시지를 볼 수 있습니다.', 'cd /tmp/lab/proj
git tag -a v1.1 -m "release 1.1"
git tag -n1

# -a : 메시지·작성자·날짜를 가진 태그 객체를 만든다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj cat-file -t v1.1)\\" = \\"tag\\" ] ) && ( git -C /tmp/lab/proj tag -n1 v1.1 | grep -q \\"release 1.1\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "v1.1 이 태그 객체이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj cat-file -t v1.1)\\" = \\"tag\\" ]"]}, {"label": "태그 메시지가 release 1.1 이다", "cmd": ["sh", "-c", "git -C /tmp/lab/proj tag -n1 v1.1 | grep -q \\"release 1.1\\""]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 6, '옛 커밋에 태그 달기', '`HEAD` 가 아니라 **바로 앞 커밋**(`add app.py` 커밋)에 태그 `v0.5` 를 다세요.', '`git tag 이름 커밋` 처럼 커밋을 지정할 수 있습니다. `HEAD~1` 은 HEAD 의 바로 앞 커밋입니다. `git log --oneline` 으로 확인하세요.', 'cd /tmp/lab/proj
git log --oneline
git tag v0.5 HEAD~1
git log --oneline --decorate

# git tag 이름 커밋 : 지정한 커밋에 태그를 단다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj rev-parse v0.5)\\" = \\"$(git -C /tmp/lab/proj rev-parse HEAD~1)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "v0.5 가 HEAD~1 을 가리킨다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-parse v0.5)\\" = \\"$(git -C /tmp/lab/proj rev-parse HEAD~1)\\" ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 7, '패턴으로 태그 찾기', '태그 중 이름이 `v1.` 로 시작하는 것만 목록으로 **`/tmp/lab/tags.txt`** 에 저장하세요.', '`git tag -l "패턴"` 은 패턴에 맞는 태그만 보여 줍니다. `*` 가 아무 글자와 맞습니다. 쉘이 `*` 를 풀지 않게 따옴표로 감싸세요.', 'cd /tmp/lab/proj
git tag -l "v1.*" > /tmp/lab/tags.txt
cat /tmp/lab/tags.txt

# git tag -l "패턴" : 패턴에 맞는 태그만', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ -s /tmp/lab/tags.txt ] && [ \\"$(cat /tmp/lab/tags.txt)\\" = \\"$(git -C /tmp/lab/proj tag -l \\"v1.*\\")\\" ] ) && ( ! grep -q \\"v0.9\\" /tmp/lab/tags.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "tags.txt 가 v1.* 태그 목록과 같다", "cmd": ["sh", "-c", "[ -s /tmp/lab/tags.txt ] && [ \\"$(cat /tmp/lab/tags.txt)\\" = \\"$(git -C /tmp/lab/proj tag -l \\"v1.*\\")\\" ]"]}, {"label": "v0.9 가 들어 있지 않다", "cmd": ["sh", "-c", "! grep -q \\"v0.9\\" /tmp/lab/tags.txt"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 8, '다른 브랜치의 커밋 하나만 가져오기 (cherry-pick)', '`feature` 브랜치에는 커밋이 두 개(`add feature file`, `add docs file`) 있습니다. `main` 에서 **`add feature file` 커밋만** 가져오세요. (`docs.txt` 는 가져오면 안 됩니다. `README.md` 의 작업 중 변경은 그대로 둡니다.)', '`git log feature --oneline` 으로 커밋 해시를 찾고, `git cherry-pick 해시` 로 그 커밋 하나를 현재 브랜치에 새 커밋으로 가져옵니다. `feature~1` 처럼 이름으로 지정해도 됩니다.', 'cd /tmp/lab/proj
git log feature --oneline
git cherry-pick feature~1
git log --oneline -3

# git cherry-pick 커밋 : 다른 브랜치의 커밋 하나를 현재 브랜치로 가져온다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"add feature file\\" ] ) && ( [ -f /tmp/lab/proj/feature.txt ] && [ ! -e /tmp/lab/proj/docs.txt ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = \\"main\\" ] && grep -q \\"draft notes\\" /tmp/lab/proj/README.md )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "main 에서 가장 최근 커밋이 add feature file 이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"add feature file\\" ]"]}, {"label": "feature.txt 는 있고 docs.txt 는 없다", "cmd": ["sh", "-c", "[ -f /tmp/lab/proj/feature.txt ] && [ ! -e /tmp/lab/proj/docs.txt ]"]}, {"label": "현재 브랜치는 main 이고 README.md 의 작업 중 변경이 남아 있다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = \\"main\\" ] && grep -q \\"draft notes\\" /tmp/lab/proj/README.md"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 9, '출처를 남기며 가져오기 (cherry-pick -x)', '이번에는 `feature` 의 **`add docs file` 커밋만** `main` 으로 가져오되, 커밋 메시지에 **원래 커밋의 해시가 기록**되게 하세요. (`feature.txt` 는 가져오면 안 됩니다.)', '`git cherry-pick -x 커밋` 은 가져온 커밋 메시지 끝에 `(cherry picked from commit ...)` 를 덧붙입니다. 가장 최근 커밋은 `feature` 로 가리킬 수 있습니다.', 'cd /tmp/lab/proj
git cherry-pick -x feature
git log -1

# -x : 메시지에 원래 커밋 해시를 남겨 출처를 알 수 있게 한다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev && git config user.email dev@example.com\\nc() { GIT_AUTHOR_NAME=$2 GIT_AUTHOR_EMAIL=$2@example.com GIT_COMMITTER_NAME=$2 GIT_COMMITTER_EMAIL=$2@example.com GIT_AUTHOR_DATE=\\"2026-01-0$3T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$3T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''# proj'' > README.md; git add README.md; c ''add README'' Ann 1\\ngit tag v0.9\\necho ''print(\\"hi\\")'' > app.py; git add app.py; c ''add app.py'' Ann 2\\necho ''echo run'' > run.sh; git add run.sh; c ''add run script'' Bob 3\\ngit tag v1.0-rc1\\ngit switch -q -c feature\\necho ''feature'' > feature.txt; git add feature.txt; c ''add feature file'' Ann 4\\necho ''docs'' > docs.txt; git add docs.txt; c ''add docs file'' Bob 5\\ngit switch -q main\\necho ''draft notes'' >> README.md\\ntrue"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"add docs file\\" ] ) && ( git -C /tmp/lab/proj log -1 --format=%B | grep -q \\"cherry picked from commit\\" ) && ( [ -f /tmp/lab/proj/docs.txt ] && [ ! -e /tmp/lab/proj/feature.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "최근 커밋이 add docs file 이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"add docs file\\" ]"]}, {"label": "메시지에 cherry picked from commit 기록이 있다", "cmd": ["sh", "-c", "git -C /tmp/lab/proj log -1 --format=%B | grep -q \\"cherry picked from commit\\""]}, {"label": "docs.txt 는 있고 feature.txt 는 없다", "cmd": ["sh", "-c", "[ -f /tmp/lab/proj/docs.txt ] && [ ! -e /tmp/lab/proj/feature.txt ]"]}]', '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 10, 'cherry-pick 이 하는 일은?', '`git cherry-pick 커밋` 이 하는 일로 알맞은 것은 무엇일까요?', '병합(merge)과는 가져오는 범위가 달라요.', NULL, NULL, '[]', 'choice', '["다른 브랜치의 모든 커밋을 현재 브랜치에 한꺼번에 합친다", "다른 브랜치의 특정 커밋만 골라 현재 브랜치에 새 커밋으로 적용한다", "현재 브랜치의 마지막 커밋을 삭제하고 이전 상태로 되돌린다", "원격 저장소의 모든 브랜치를 새로 내려받아 덮어쓴다"]', 1, '`cherry-pick` 은 지정한 커밋의 변경만 현재 브랜치에 **새 커밋** 으로 적용합니다(해시는 달라집니다). 브랜치 전체를 합치는 것은 `merge`, 커밋을 되돌리는 것은 `reset`·`revert`, 원격 내용을 받는 것은 `fetch`·`pull` 입니다.', NULL, NULL, NULL, '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 11, '치워 둔 작업 꺼내기', '보관함의 가장 최근 항목을 작업 폴더에 **되살리고 보관함에서도 지우는** 명령입니다. 빈칸을 채우세요.', '꺼내서 지운다는 뜻이에요. 목록만 보거나 지우기만 하는 것이 아닙니다.', NULL, NULL, '[]', 'fill', '["pop", "list", "drop", "show"]', NULL, '`git stash pop` 은 되살리고 보관함에서 지웁니다. `list` 는 목록만 보고, `drop` 은 되살리지 않고 지우기만 하며, `show` 는 내용을 보여 줍니다. 지우지 않고 되살리기만 하려면 `git stash apply` 입니다.', '[0]', 'git stash {0}', NULL, '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 368, 12, '급한 수정이 끼어들 때의 흐름', '작업 중인 변경이 있는데 다른 브랜치에서 급한 수정을 해야 할 때의 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '치우기 → 이동·수정 → 돌아오기 → 되살리기 순서예요.', NULL, NULL, '[]', 'order', '["`git stash` 로 하던 작업을 잠시 치운다", "다른 브랜치로 옮겨 급한 수정을 하고 커밋한다", "원래 브랜치로 돌아온다", "`git stash pop` 으로 치워 둔 작업을 되살린다"]', NULL, '하던 변경을 `stash` 로 치우고, 다른 브랜치에서 급한 일을 끝낸 뒤, 원래 브랜치로 돌아와 `stash pop` 으로 이어서 작업합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "git stash 문서", "url": "https://git-scm.com/docs/git-stash"}, {"title": "git tag 문서", "url": "https://git-scm.com/docs/git-tag"}, {"title": "git cherry-pick 문서", "url": "https://git-scm.com/docs/git-cherry-pick"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 368 AND order_index = 12);

